	'messages:permissionserrors' => 'io:Eroro permisal',
	'messages:permissionserrorstext' => 'io:Vu ne darfas facar to, pro la sequanta {{PLURAL:$1|motivo|motivi}}:',
	'messages:permissionserrorstext-withaction' => 'io:Vu ne darfas $2, pro la {{PLURAL:$1|kauzo|kauzi}} sequanta:',
	'messages:contentmodelediterror' => 'io:Vu ne povas redaktar ca revizo, nam ol uzas la modelo <code>$1</code>, qua esas diferanta de la nuna modelo di pagino, <code>$2</code>',
	'messages:recreate-moveddeleted-warn' => 'io:<strong>Atencez: Vu rikreos pagino qua antee efacesis.</strong>

